      const g = pillar(V, r.T, '#7fd6ff', 'sky-beam');
      MB.audio.sfx('splash');
      await gsap.fromTo(g.body, { scaleX: 0 }, { scaleX: 1.3, duration: 0.15 });
      for (let i = 0; i < (o.hits || 1); i++) land(i);
