    MB.audio.sfx('zip');
    await gsap.to(v.el, { x: T.x + R, y: T.y, duration: 0.25, ease: 'power2.in', onUpdate: () => ghost(V, v, c) });
    if (!PLUG) gsap.set(strokes, { opacity: 1 });
