    await gsap.to(big.body, { y: -hT * 0.9, rotation: sg * 25, duration: 0.25, ease: EASE.drop });
    impact(); hit(V, t, c, true); MB.audio.sfx('gavel', { rate: 0.8 }); MB.audio.sfx('slam'); V.shake(22); V.hitStop();
