    beams.forEach((b) => gsap.to(b.body, { scaleX: 0, opacity: 0, duration: 0.4, onComplete: () => b.remove() }));
    pop(V, T, hT + 120, own(a, 'finish', 'Bless your heart, dear.'), 'float-text heal', 1.1);
