    const src = L.tagName === 'IMG' ? L.src : '', fl = V.billboard('ghost clone flyer', src ? `<img src="${src}">` : L.outerHTML, A.x, A.y);
    fl.body.style.setProperty('--c', c); fl.body.style.height = (parseFloat(L.style.height) || V.heightOf(a)) + 'px';
