    gsap.fromTo(v.figure, { scaleY: 0.92 }, { scaleY: 1, duration: 0.3, ease: 'elastic.out(1,0.4)' });
    pop(V, A, H + 95, own(a, 'cry', 'Measure twice, hit once!'), 'float-text buff', 1.1);
    const bp = V.flat('blueprint', '<i></i>', T.x, T.y);
    MB.audio.sfx('crinkle');
