    gsap.fromTo(bell.body, { rotation: -25 }, { rotation: 25, duration: 0.1, repeat: 7, yoyo: true, onComplete: () => gsap.to(bell.body, { scale: 0, duration: 0.2, onComplete: () => bell.remove() }) });
    pop(V, A, H + 110, 'DING DONG!', 'float-text buff', 0.8);
