    const follow = () => { const x = gsap.getProperty(v.el, 'x'), y = gsap.getProperty(v.el, 'y'); toasts.forEach((b, i) => gsap.set(b, { x: x + (i ? 50 : -50), y })); };
    const legs = gsap.to([L, R], { y: -18, duration: 0.07, stagger: 0.035, yoyo: true, repeat: -1 });
