    tint(vt, 'sepia(1) saturate(6) hue-rotate(-40deg) brightness(0.9)', 1);
    for (let i = 0; i < 16; i++) { const s = dot(V, T, hT, MB.pick([c, c, '#1a0a0a']), rnd(8, 18)); toss(s, { v: [260, 560], dur: 0.9 }); }
    decal(V, T, 'splat', c, 1);
    scatter(V, T, hT, ['❤️', '⚡', '✨'], 10, 160);
