    buoy.body.style.fontSize = '90px';
    MB.audio.sfx('whoosh');
    await path(buoy, (k) => ({ ...arc(P0, T, H * 0.6, hT * 0.7, 200)(k), r: k * 720 }), 0.55, 'sine.inOut');
