    MB.audio.sfx('whoosh');
    await gsap.to(gav.body, { rotation: 10, duration: 0.15, ease: 'power4.in' });
    MB.audio.sfx('gavel'); ring(V, T, c, 1.2);
    fadeOut(gav, 0.2);
    // the frame drops
