    impact(); hit(V, t, c, true); MB.audio.sfx('stab'); MB.audio.sfx('slam'); V.shake(26); V.hitStop();
    squash(vt, 0.45);
    cracks(V, T, '#2b1d12', { n: 9, len: 170, w: 6, glow: c });
    debris(V, T, '#c9b79c', 12, { spread: 190 });
    fadeOut(spear, 0.2);
    await wait(0.35);
