    await wait(0.4);
    pop(V, sideOf(A, 0), H + 70, 'Cute. Mine.', 'float-text debuff', 0.9);
    const B = { x: lerp(A.x, T.x, 0.5), y: lerp(A.y, T.y, 0.5) + 70 }, bob = V.billboard('thrown', '🤖', B.x, B.y);
