    const bot = V.billboard('thrown', '🤖', P0.x, P0.y);
    bot.body.style.fontSize = '64px';
    gsap.set(bot.body, { y: -30 });
    gsap.fromTo(bot.body, { scale: 0 }, { scale: 1, duration: 0.25, ease: 'back.out(3)' });
    await wait(0.3);
