    gsap.set(con.body, { y: -top - 110 });
    gsap.fromTo(con.body, { opacity: 0 }, { opacity: 1, duration: 0.2 });
    MB.audio.sfx('click');
    await wait(0.5);
    impact(); hit(V, t, c, true); MB.audio.sfx('glitch'); MB.audio.sfx('boom'); V.shake(20); V.hitStop();
    tint(vt, 'invert(1) hue-rotate(90deg)', 0.6);
