      MB.audio.sfx('whistleUp');
      await path(r, along(arc(P, Q, 20, top, 140), 45), 0.55, 'power1.out', (p) => {
        if (Math.random() < 0.7) { const s = dot(V, p, p.h, '#ffb347', 8); gsap.to(s.body, { opacity: 0, scale: 0.2, duration: 0.4, onComplete: () => s.remove() }); }
      });
