    sigil.body.style.fontSize = '84px'; sigil.body.style.filter = `drop-shadow(0 0 14px ${blood})`;
    gsap.fromTo(sigil.body, { scale: 0, rotation: -40 }, { scale: 1, rotation: 0, duration: 0.35, ease: 'back.out(2)' });
    MB.audio.sfx('dark');
