    await wait(0.45);
    MB.audio.sfx('unlock');
    key.animate(sjms(0.2)).transform({ translateX: W / 2 - 56, translateY: H * 0.55, rotate: 0, scaleY: 0.3 });
    await wait(0.25);
    MB.audio.sfx('creak');
    door.animate(sjms(0.25)).ease('<').transform({ scaleX: 0.08, origin: [10, H / 2] });
    key.animate(sjms(0.2)).attr({ opacity: 0 });
